from jsonb_to_recordset($wall_questions$[{"id":"u01_l01_q093","lesson_id":"u01_l01","difficulty":"medium","prompt":"أي العبارات أدق في بيان مسؤولية الإنسان عما يدور في نفسه وفق شرح الآيات؟","options":[{"id":"o4","text":"لا يتحمل مسؤولية الأفعال الاختيارية"},{"id":"o3","text":"لا يحاسب على الأقوال الظاهرة"},{"id":"o1","text":"لا يؤاخذ على الخاطر ما لم يعمل به أو يتكلم"},{"id":"o2","text":"يحاسب على كل خاطر مهما كان عابرًا"}],"correct_id":"o1","explanation":"ذكر الكتاب التجاوز عن حديث النفس ما لم يتحول إلى عمل أو قول.","page":8},{"id":"u01_l01_q106","lesson_id":"u01_l01","difficulty":"medium","prompt":"ما الذي يجعل الاستغفار مناسبًا لحال المسلم حتى مع التزامه بطاعة الله؟","options":[{"id":"o2","text":"امتناع الإنسان عن الوقوع في أي خطأ"},{"id":"o1","text":"تعرض الإنسان للخطأ والتقصير واحتياجه إلى المغفرة"},{"id":"o3","text":"انحصار الاستغفار في غير المؤمنين"},{"id":"o4","text":"انتفاء علاقة العمل بصدق الإيمان"}],"correct_id":"o1","explanation":"بين الكتاب أن الإنسان معرض للتقصير ولذلك يسارع إلى طلب المغفرة.","page":10},{"id":"u01_l01_q107","lesson_id":"u01_l01","difficulty":"medium","prompt":"حين تردد الصحابة «سمعنا وأطعنا» بعد توجيه النبي ﷺ، فأي موقف عبّروا عنه؟","options":[{"id":"o1","text":"التسليم لله بدل الاعتراض على أمره"},{"id":"o2","text":"رفض التكاليف الشرعية جميعًا"},{"id":"o3","text":"تحديد وقت الحساب"},{"id":"o4","text":"الاستغناء عن طلب المغفرة"}],"correct_id":"o1","explanation":"توضح رواية سبب النزول في الصفحة 12 استجابة الصحابة بالتسليم.","page":12},{"id":"u01_l01_q108","lesson_id":"u01_l01","difficulty":"medium","prompt":"أي نتيجة عملية تترتب على الاعتقاد بأن ملك الله يشمل الكون كله؟","options":[{"id":"o4","text":"حصر عظمة الخالق فيما يرى بالعين"},{"id":"o3","text":"الخوف من كل مخلوق بصفته مالكًا مستقلًا"},{"id":"o2","text":"اعتقاد استقلال المخلوقات عن خالقها"},{"id":"o1","text":"استشعار رعايته والطمأنينة إليه"}],"correct_id":"o1","explanation":"ربط شرح عموم الملك بعظمة الله وطمأنينة الإنسان في رعايته.","page":8},{"id":"u01_l01_q116","lesson_id":"u01_l01","difficulty":"medium","prompt":"لماذا تكرر نداء «ربنا» في أدعية الآية الأخيرة من سورة البقرة وفق الشرح؟","options":[{"id":"o4","text":"لإثبات أن الدعاء يغني عن الطاعة"},{"id":"o1","text":"لإظهار التذلل والإلحاح في طلب الاستجابة"},{"id":"o2","text":"للتقليل من أهمية الدعاء"},{"id":"o3","text":"للدلالة على استقلال الإنسان عن ربه"}],"correct_id":"o1","explanation":"عدّ الكتاب تكرار النداء من آداب الدعاء الدالة على التذلل والرغبة والإلحاح.","page":11},{"id":"u01_l01_q123","lesson_id":"u01_l01","difficulty":"hard","prompt":"قال طالب: «الله يعلم النيات، ولذلك يُحاسَب الإنسان على كل خاطر عابر». ما موضع الخلل في استنتاجه؟","options":[{"id":"o2","text":"اعتقد أن الله يعلم السرائر"},{"id":"o1","text":"تجاهل تجاوز الله عن حديث النفس ما لم يتحول إلى قول أو عمل"},{"id":"o4","text":"ذكر أن المحاسبة تشمل الأعمال الظاهرة"},{"id":"o3","text":"ربط النية بسلوك الإنسان"}],"correct_id":"o1","explanation":"يفرق الدرس بين إحاطة علم الله بالخواطر وبين عدم المؤاخذة على ما لم يُعمل به أو يُتكلّم.","page":8},{"id":"u01_l01_q129","lesson_id":"u01_l01","difficulty":"medium","prompt":"أي تمييز أدق بين طلب العفو وطلب الرحمة في أدعية آخر سورة البقرة؟","options":[{"id":"o1","text":"العفو طلب ترك المؤاخذة والرحمة طلب الإحسان والفضل"},{"id":"o4","text":"العفو طلب التشديد والرحمة طلب العقوبة"},{"id":"o2","text":"العفو طلب النصر والرحمة طلب البيان"},{"id":"o3","text":"العفو طلب المال والرحمة طلب الصحة"}],"correct_id":"o1","explanation":"تتضمن أدعية الآية طلب التجاوز عن الذنب وطلب الفضل والإحسان.","page":11},{"id":"u01_l01_q135","lesson_id":"u01_l01","difficulty":"medium","prompt":"من قال إنه يصدق رسالة محمد ﷺ لكنه يرفض الاعتراف برسالة رسول سابق، ما الذي خالفه؟","options":[{"id":"o4","text":"يسر التكاليف الشرعية"},{"id":"o3","text":"طلب العفو عند الخطأ"},{"id":"o2","text":"وجوب الصدقة وحدها"},{"id":"o1","text":"وجوب الإيمان بجميع الرسل دون تفريق"}],"correct_id":"o1","explanation":"تقرر الآية (285) عدم التفريق بين الرسل في وجوب الإيمان بهم جميعًا.","page":10},{"id":"u01_l01_q136","lesson_id":"u01_l01","difficulty":"medium","prompt":"ما الموقف الذي يجعل قول المؤمن «سمعنا وأطعنا» أصدق تعبيرًا عن إيمانه؟","options":[{"id":"o4","text":"ترك العمل بحجة الاستغفار"},{"id":"o3","text":"الاكتفاء بإعلان الإيمان دون عمل"},{"id":"o1","text":"العمل بالأمر المشروع مع الرضا والتسليم"},{"id":"o2","text":"تأجيل العمل حتى تزول كل مشقة"}],"correct_id":"o1","explanation":"يبين الدرس أن الإيمان إقرار وخضوع يتبعه العمل والامتثال.","page":10},{"id":"u01_l01_q137","lesson_id":"u01_l01","difficulty":"hard","prompt":"أخطأ إنسان ثم أسرع إلى الاستغفار بدل الإصرار على الذنب؛ فأي معنى في شرح الآية (285) يطبّقه؟","options":[{"id":"o1","text":"المبادرة إلى طلب المغفرة عند التقصير"},{"id":"o2","text":"إسقاط المسؤولية عن الأفعال المقصودة"},{"id":"o3","text":"إنكار الحساب في الآخرة"},{"id":"o4","text":"اشتراط العصمة لقبول العمل"}],"correct_id":"o1","explanation":"يقرر الدرس أن الإنسان معرض للخطأ وعليه المسارعة إلى طلب المغفرة.","page":10},{"id":"u01_l01_q141","lesson_id":"u01_l01","difficulty":"medium","prompt":"إذا تردّد إنسان في الإقدام على معصية لا يراه فيها أحد ثم امتنع عنها، فأي حقيقة من شرح الآية (284) استحضرها؟","options":[{"id":"o4","text":"عدم مسؤولية المرء عن اختياره"},{"id":"o2","text":"اقتصار الحساب على الأقوال العلنية"},{"id":"o1","text":"علم الله بالسرائر والنوايا"},{"id":"o3","text":"اختصاص الثواب بالعبادات الظاهرة"}],"correct_id":"o1","explanation":"يوضّح الدرس شمول علم الله تعالى لما يُظهره الإنسان وما يُخفيه، وأثر ذلك في ضبط سلوكه.","page":8},{"id":"u01_l01_q144","lesson_id":"u01_l01","difficulty":"medium","prompt":"ما دلالة اقتران إيمان المؤمنين بإيمان الرسول في شرح الآية (285)؟","options":[{"id":"o2","text":"اعتبار المؤمنين أنبياء"},{"id":"o4","text":"اختصاص الإيمان بزمن نزول الآية"},{"id":"o1","text":"تكريم المؤمنين والثناء عليهم"},{"id":"o3","text":"إسقاط واجب الطاعة عنهم"}],"correct_id":"o1","explanation":"نص الدرس على أن ذكر إيمان المؤمنين مع إيمان الرسول ﷺ زيادة في تكريمهم.","page":9},{"id":"u01_l01_q145","lesson_id":"u01_l01","difficulty":"medium","prompt":"إذا اعترف شخص بصحة حكم شرعي ثم تعمّد مخالفته مع القدرة، فأي جانب من حقيقة الإيمان لم يحققه في الموقف؟","options":[{"id":"o3","text":"حفظ ترتيب الآيات"},{"id":"o2","text":"معرفة اسم السورة"},{"id":"o1","text":"الاستسلام العملي لأمر الله"},{"id":"o4","text":"معرفة عدد الرسل"}],"correct_id":"o1","explanation":"بيّن الدرس أن التصديق يقترن بالخضوع والعمل والانقياد للأوامر والنواهي.","page":10},{"id":"u01_l01_q147","lesson_id":"u01_l01","difficulty":"medium","prompt":"أي دعاء في الآية (286) يتعلّق صراحةً بالتقصير الذي يقع بسبب السهو أو الخطأ؟","options":[{"id":"o3","text":"طلب الاستعانة في شؤون الحياة"},{"id":"o2","text":"طلب النصر على المعتدين"},{"id":"o4","text":"طلب زيادة الملك في الدنيا"},{"id":"o1","text":"طلب عدم المؤاخذة بالنسيان والخطأ"}],"correct_id":"o1","explanation":"فرّق الدرس بين الطلب من الله عدم المؤاخذة بسبب النسيان والخطأ وسائر الأدعية.","page":11},{"id":"u01_l01_q151","lesson_id":"u01_l01","difficulty":"medium","prompt":"إذا استدلّ طالب بلفظ العموم في مطلع الآية (284)، فأي نتيجة يؤيدها استدلاله؟","options":[{"id":"o1","text":"أن ما في السماوات والأرض داخل في ملك الله تعالى"},{"id":"o4","text":"أن الرحمة تنفي قدرة الله على الحساب"},{"id":"o2","text":"أن الإنسان يملك الكون ملكًا مطلقًا"},{"id":"o3","text":"أن علم الله مقصور على ما يُعلن"}],"correct_id":"o1","explanation":"شرح الدرس دلالة اللفظ العام على شمول ملك الله جميع الموجودات.","page":8},{"id":"u01_l01_q154","lesson_id":"u01_l01","difficulty":"easy","prompt":"وفق شرح الآية (285)، ما الذي يميز الإيمان بالرسل جميعًا عن اختيار الإيمان ببعضهم؟","options":[{"id":"o2","text":"أنه يقتصر على رسول واحد من غير سواه"},{"id":"o3","text":"أنه يعتمد على الانتماء الجغرافي للرسول"},{"id":"o4","text":"أنه يجعل الرسالات السابقة غير موجودة"},{"id":"o1","text":"أنه يتضمن التصديق بكل الرسل الذين بعثهم الله"}],"correct_id":"o1","explanation":"يؤكد الكتاب وجوب الإيمان بالرسل جميعًا وعدم التفريق بينهم في أصل التصديق.","page":9},{"id":"u01_l01_q157","lesson_id":"u01_l01","difficulty":"medium","prompt":"ما الفرق بين سؤال العفو وسؤال المغفرة كما يظهر في خاتمة الآية (286)؟","options":[{"id":"o2","text":"أن كليهما طلب زيادة المال دون ارتباط بالتقصير"},{"id":"o1","text":"هما دعاءان متمايزان يجتمعان في طلب فضل الله ورحمته"},{"id":"o4","text":"أن المقصود بهما إلغاء كل واجب على الإنسان"},{"id":"o3","text":"أن العفو يُطلب من الناس فقط والمغفرة لا تُطلب"}],"correct_id":"o1","explanation":"سردت خاتمة الآية طلب العفو والمغفرة والرحمة في سياق افتقار المؤمن إلى ربه.","page":11},{"id":"u01_l01_q161","lesson_id":"u01_l01","difficulty":"medium","prompt":"يحرص طالب على أداء واجبه حتى عندما لا يراه أحد؛ أي حقيقة في شرح الآية (284) تؤسس لهذا السلوك؟","options":[{"id":"o3","text":"أن الحساب يختص بالأفعال المعلنة فقط"},{"id":"o4","text":"أن الخواطر المجردة تُعدّ جميعًا أفعالًا محرمة"},{"id":"o1","text":"إحاطة علم الله بالأعمال الظاهرة والنوايا الباطنة"},{"id":"o2","text":"أن مسؤولية الإنسان تتوقف عند رقابة الناس"}],"correct_id":"o1","explanation":"يربط الكتاب بين شمول علم الله للظاهر والباطن واستقامة المؤمن في سلوكه.","page":8},{"id":"u01_l01_q168","lesson_id":"u01_l01","difficulty":"medium","prompt":"لماذا كان توجيه النبي ﷺ للصحابة بقول سمعنا وأطعنا حاسمًا في رواية سبب النزول؟","options":[{"id":"o3","text":"لأنه منعهم من طلب المغفرة"},{"id":"o4","text":"لأنه أوصى بترك الصلوات والصيام"},{"id":"o1","text":"لأنه أكد التسليم لأمر الله قبل بيان التخفيف"},{"id":"o2","text":"لأنه علق الالتزام على موافقة الناس"}],"correct_id":"o1","explanation":"أظهرت الرواية انتقال الصحابة إلى التسليم والطاعة ثم نزول الآية التي ترفع الحرج.","page":12},{"id":"u01_l01_q171","lesson_id":"u01_l01","difficulty":"easy","prompt":"على ماذا يدل عموم ما في السماوات وما في الأرض في بيان عظمة الله تعالى؟","options":[{"id":"o2","text":"أن ملك الله مقصور على الأرض"},{"id":"o1","text":"أن ملك الله يشمل جميع ما في الكون"},{"id":"o3","text":"أن ملك الله يختص بما يراه الإنسان"},{"id":"o4","text":"أن ملك الله يتغير باختلاف الأزمنة"}],"correct_id":"o1","explanation":"قرر الدرس أن كل ما في السماوات والأرض ملك لله تعالى وأن اللفظ يفيد العموم.","page":8},{"id":"u01_l01_q172","lesson_id":"u01_l01","difficulty":"medium","prompt":"من يتجنب المعصية في خلوته استحضارًا لعلم الله؛ أي صلة بين الاعتقاد والعمل يوضحها هذا الموقف؟","options":[{"id":"o1","text":"الإيمان بإحاطة العلم الإلهي يوجّه السلوك في السر والعلن"},{"id":"o3","text":"ترك المحاسبة على الأقوال الباطنة يعني إباحة الأعمال المحرمة"},{"id":"o2","text":"معرفة الناس بالعمل هي أساس صلاح النية"},{"id":"o4","text":"سعة الملك تمنع الإنسان من الاختيار"}],"correct_id":"o1","explanation":"ربط شرح الآية بين شمول علم الله للنوايا والأفعال وبين ضبط المسلم لتصرفاته.","page":8},{"id":"u01_l01_q174","lesson_id":"u01_l01","difficulty":"medium","prompt":"لماذا قرن شرح الآيات صدق الإيمان بالعمل بعد الإقرار والتصديق؟","options":[{"id":"o4","text":"لأن الخطأ يمنع طلب المغفرة مطلقًا"},{"id":"o1","text":"لأن الطاعة والامتثال دليلان على حقيقة الإيمان"},{"id":"o3","text":"لأن الإيمان يقتصر على معرفة المعلومات"},{"id":"o2","text":"لأن العمل يغني عن الاعتقاد بأركان الإيمان"}],"correct_id":"o1","explanation":"بيّن الدرس أن الإيمان تصديق وإقرار وخضوع يتبعه عمل يدل على صدقه.","page":10},{"id":"u01_l01_q176","lesson_id":"u01_l01","difficulty":"medium","prompt":"أي موقف يعبّر عن مبدأ تحمل الإنسان تبعة ما كسبه في الآية (286)؟","options":[{"id":"o2","text":"يُحاسَب كل فرد على أخطاء أفراد أسرته"},{"id":"o3","text":"تنتهي مسؤولية الشخص إذا لم يره الناس"},{"id":"o4","text":"لا أثر للعمل الصالح في حساب العبد"},{"id":"o1","text":"يعترف المرء بخطئه ويعمل على إصلاحه بدل إلقاء اللوم على غيره"}],"correct_id":"o1","explanation":"تقرر الآية مسؤولية الإنسان عن عمله وما كسبه من خير أو شر.","page":10},{"id":"u01_l01_q178","lesson_id":"u01_l01","difficulty":"easy","prompt":"أي موقف ظهر من الصحابة بعد توجيه النبي ﷺ في رواية سبب نزول خواتيم البقرة؟","options":[{"id":"o2","text":"الإصرار على رفض التكليف كله"},{"id":"o4","text":"الاعتراض على أركان الإيمان"},{"id":"o3","text":"التوقف عن تعلم القرآن الكريم"},{"id":"o1","text":"الإقرار بالسمع والطاعة والاستغفار"}],"correct_id":"o1","explanation":"أورد الدرس أن الصحابة قالوا سمعنا وأطعنا وغفرانك ربنا وإليك المصير.","page":12},{"id":"u01_l01_q182","lesson_id":"u01_l01","difficulty":"medium","prompt":"من رجع عن معصية ولم يجعل سعة رحمة الله ذريعة للإصرار عليها؛ أي فهم ينسجم مع شرح الآية 284؟","options":[{"id":"o1","text":"يجمع بين رجاء مغفرة الله والامتناع عن المعصية"},{"id":"o2","text":"يجزم بأن التوبة لا تنفع بعد الذنب"},{"id":"o4","text":"يظن أن القدرة الإلهية لا تتعلق بالأفعال"},{"id":"o3","text":"يعد كل خاطر عابر ذنبًا يعاقب عليه"}],"correct_id":"o1","explanation":"أشار الدرس إلى المغفرة لمن تاب وإلى التوازن بين الخوف والرجاء.","page":8},{"id":"u01_l01_q183","lesson_id":"u01_l01","difficulty":"medium","prompt":"طالب يؤمن بالرسل لكنه يرفض أصل الإيمان بالكتب التي أنزلها الله؛ ما وجه الخلل وفق حقائق الآية 285؟","options":[{"id":"o4","text":"اقتصر الخلل على ترك سنّة مستحبة"},{"id":"o2","text":"أتى بكل أركان الإيمان المذكورة"},{"id":"o3","text":"حقق معنى الإقرار والطاعة كاملًا"},{"id":"o1","text":"فصل بين ركنين من أركان الإيمان الواجب التصديق بهما"}],"correct_id":"o1","explanation":"تورد الآية والشرح وجوب الإيمان بالرسل والكتب ضمن حقائق الإيمان.","page":9},{"id":"u01_l01_q185","lesson_id":"u01_l01","difficulty":"medium","prompt":"كيف تجمع الآية 285 بين وحدة مصدر الرسالات وموقف المؤمن من الرسل؟","options":[{"id":"o3","text":"تعتبر الرسالات متعارضة في أصل التوحيد"},{"id":"o1","text":"تلزمه الإيمان بهم جميعًا من غير تفريق"},{"id":"o4","text":"تحصر طاعة الله في أقوال الناس"},{"id":"o2","text":"تجيز له إنكار رسالة أحدهم لقدم عهده"}],"correct_id":"o1","explanation":"شرح الدرس عدم التفريق بين الرسل وأن رسالة سيدنا محمد ﷺ امتداد وخاتمة للرسالات.","page":10},{"id":"u01_l01_q186","lesson_id":"u01_l01","difficulty":"medium","prompt":"ما الفارق بين طلب رفع الإصر وطلب عدم تحميل ما لا طاقة به في دعاء الآية 286؟","options":[{"id":"o4","text":"لا فرق بينهما لأنهما دعاء بالرزق فقط"},{"id":"o2","text":"الأول طلب النصر والثاني طلب المغفرة"},{"id":"o1","text":"الأول رفع التكليف الشاق والثاني دفع ما يتجاوز القدرة"},{"id":"o3","text":"الأول الإيمان بالملائكة والثاني الإيمان بالكتب"}],"correct_id":"o1","explanation":"فسر الدرس الإصر بالتكاليف الثقيلة وبيّن الدعاء بعدم حمل ما لا قدرة عليه.","page":11},{"id":"u01_l02_q106","lesson_id":"u01_l02","difficulty":"medium","prompt":"ما الوظيفة التي تؤديها الدلائل النقلية إذا ضعفت الفطرة أو ضل العقل؟","options":[{"id":"o2","text":"إلغاء الحاجة إلى العبادة"},{"id":"o1","text":"إرشاد الناس إلى العقيدة الصحيحة بواسطة الرسل"},{"id":"o3","text":"إثبات أن الوحي من صنع البشر"},{"id":"o4","text":"حصر الهداية في مراقبة الكواكب"}],"correct_id":"o1","explanation":"يذكر الدرس حاجة الناس إلى رسل يبلغون العقيدة الصحيحة.","page":17},{"id":"u01_l02_q108","lesson_id":"u01_l02","difficulty":"medium","prompt":"ما وجه الخلل في تشبيه نشأة الكون بسقوط حروف تتكون منها قصيدة كاملة بالمصادفة؟","options":[{"id":"o4","text":"القول إن الكون لا يحتوي مخلوقات"},{"id":"o1","text":"تجاهل ما يتطلبه النظام المحكم من ترتيب وإتقان"},{"id":"o2","text":"إثبات أن كل الحروف متماثلة"},{"id":"o3","text":"جعل اللغة مصدر التشريع الثاني"}],"correct_id":"o1","explanation":"المثال في الإثراء ينتقد إرجاع النظام المحكم إلى المصادفة المحضة.","page":18},{"id":"u01_l02_q113","lesson_id":"u01_l02","difficulty":"medium","prompt":"لماذا لا يَقبل دليل السببية أن تكون المخلوقات قد أوجدت نفسها؟","options":[{"id":"o3","text":"لأن الإنسان يستطيع خلق كل ما يحيط به"},{"id":"o4","text":"لأن السبب يأتي دائمًا بعد النتيجة"},{"id":"o2","text":"لأن جميع الموجودات متساوية في الحجم"},{"id":"o1","text":"لأن الشيء كان معدومًا قبل وجوده فلا يخلق نفسه"}],"correct_id":"o1","explanation":"يبين الدرس أن الموجود لم يكن موجودًا قبل أن يوجد فلا يعقل أن يخلق نفسه بنفسه.","page":15},{"id":"u01_l02_q120","lesson_id":"u01_l02","difficulty":"hard","prompt":"إذا لم يستطع باحث الاستدلال من سلوك النمل على الهداية، فأي دليل من سلوك المخلوقات يصلح للمقارنة؟","options":[{"id":"o2","text":"اختيار الورثة أنصبتهم بأنفسهم"},{"id":"o1","text":"اهتداء المولود إلى الرضاعة منذ ولادته"},{"id":"o3","text":"وضع الأنظمة للمؤسسات"},{"id":"o4","text":"تحديد مواعيد السفر"}],"correct_id":"o1","explanation":"ساق الكتاب هداية المولود إلى الرضاعة وهداية النملة إلى غذائها مثالين من النوع نفسه.","page":17},{"id":"u01_l02_q133","lesson_id":"u01_l02","difficulty":"medium","prompt":"مزارع يرى تباين ثمار نباتات تُسقى بماء واحد؛ فأي دلالة يُستثمر هذا المشهد لإيضاحها؟","options":[{"id":"o2","text":"حصر الهداية بالإنسان"},{"id":"o4","text":"انعدام الترابط بين المخلوقات"},{"id":"o1","text":"الإتقان والتنوع في الخلق"},{"id":"o3","text":"توقف الكون عن الحركة"}],"correct_id":"o1","explanation":"استشهد الدرس باختلاف الثمار رغم وحدة الأرض والماء ضمن مظاهر الإتقان.","page":16},{"id":"u01_l02_q142","lesson_id":"u01_l02","difficulty":"hard","prompt":"إذا استُعمل مثال إنسان يطلب النجدة من خالقه حين انقطاع أسباب النجاة، فما الجانب الذي يجعله دليلًا فطريًا لا نقليًا؟","options":[{"id":"o3","text":"تعلقه بإحصاء أسانيد الأحاديث"},{"id":"o1","text":"صدور الشعور من أعماق النفس قبل الاستدلال بنص"},{"id":"o2","text":"اعتماده على قياس أطوال الأجرام"},{"id":"o4","text":"ارتباطه بقوانين الوراثة"}],"correct_id":"o1","explanation":"الدرس يصف الفطرة بأنها اطمئنان مودع في القلب يظهر في أوقات الشدة.","page":15},{"id":"u01_l02_q145","lesson_id":"u01_l02","difficulty":"medium","prompt":"أي استنتاج ينسجم مع ذكر دوران الأرض حول الشمس ودورانها حول نفسها في دليل الإتقان؟","options":[{"id":"o2","text":"كل الحركات تقع بلا انتظام"},{"id":"o4","text":"تعاقب الليل والنهار ظاهرة عشوائية"},{"id":"o1","text":"لكل حركة نظام تتصل به ظواهر محددة"},{"id":"o3","text":"الفصول لا تتصل بحركة الأرض"}],"correct_id":"o1","explanation":"أورد الدرس الحركتين وما يتبعهما من اختلاف الفصول وتعاقب الليل والنهار.","page":16},{"id":"u01_l02_q151","lesson_id":"u01_l02","difficulty":"medium","prompt":"إذا شعر الإنسان بحاجته إلى خالقه في شدة لا يجد فيها عونًا، فأي عنصر من الدليل الفطري يبرز؟","options":[{"id":"o3","text":"أن اليقين لا يتأثر بالتجارب مطلقًا"},{"id":"o4","text":"أن الحاجة إلى العون تنفي وجود الخالق"},{"id":"o1","text":"وجود شعور أصيل باللجوء إلى الله عند الشدائد"},{"id":"o2","text":"قدرة الإنسان على خلق ذاته وقت الأزمات"}],"correct_id":"o1","explanation":"فسّر الكتاب دليل الفطرة بما أودع الله في الإنسان من شعور بوجود خالق يلجأ إليه.","page":15},{"id":"u01_l02_q153","lesson_id":"u01_l02","difficulty":"medium","prompt":"كيف يختلف الاستدلال بتناسق أجزاء العين عن الاستدلال بمجرد وجودها؟","options":[{"id":"o1","text":"إنه ينظر في إحكام وظائف الأجزاء وترابطها"},{"id":"o3","text":"إنه يقتصر على وصف حجم العين"},{"id":"o4","text":"إنه يحصر الإتقان في الأشياء المصنوعة فقط"},{"id":"o2","text":"إنه يعدّ العين غير محتاجة إلى أي نظام"}],"correct_id":"o1","explanation":"يعرض الدرس العين مثالًا على إحكام الخلق وتكامل أجزائه في دليل الإتقان.","page":16},{"id":"u01_l02_q155","lesson_id":"u01_l02","difficulty":"medium","prompt":"لماذا تعد قدرة الرضيع على الرضاعة من الأم مثالًا على الهداية؟","options":[{"id":"o4","text":"لأن جميع المخلوقات تستغني عن الغذاء"},{"id":"o1","text":"لأن المخلوق يهتدي إلى ما يصلح معاشه منذ بدايات حياته"},{"id":"o2","text":"لأن الرضيع يكتسب مهاراته من كتب التاريخ"},{"id":"o3","text":"لأن الاهتداء محصور في الإنسان البالغ"}],"correct_id":"o1","explanation":"أورد الدرس اهتداء المولود إلى الرضاعة دليلًا على هداية الله للمخلوقات.","page":17},{"id":"u01_l02_q172","lesson_id":"u01_l02","difficulty":"medium","prompt":"إذا سأل طالب: لماذا لا يكون الكون قد أوجد نفسه؟ فأي إجابة تنتمي إلى دليل السببية؟","options":[{"id":"o2","text":"حركة النملة في طلب طعامها دليل على الهداية فقط"},{"id":"o1","text":"المعدوم قبل وجوده لا يستطيع إيجاد نفسه"},{"id":"o4","text":"الفطرة تمنع الإنسان من طرح أي سؤال"},{"id":"o3","text":"تنوع الألوان في الثمار شاهد على حسن الخلق"}],"correct_id":"o1","explanation":"شرح الكتاب أن الشيء كان عدمًا قبل وجوده فلا يمكن أن يكون سبب إيجاد نفسه.","page":15},{"id":"u01_l02_q174","lesson_id":"u01_l02","difficulty":"medium","prompt":"على ماذا يستدل اختلاف ثمار النباتات في الطعم واللون والرائحة مع اشتراكها في الأرض والماء؟","options":[{"id":"o3","text":"أن تنوع المخلوقات دليل على الفوضى"},{"id":"o4","text":"أن التماثل التام شرط وجود الخالق"},{"id":"o2","text":"أن النبات الواحد لا يحتاج إلى الماء"},{"id":"o1","text":"دقة الخلق وتنوعه على نحو يدل على الإتقان"}],"correct_id":"o1","explanation":"عرض الدرس تنوع الثمار رغم وحدة أسباب النمو في أمثلة إتقان الخلق.","page":16},{"id":"u01_l02_q177","lesson_id":"u01_l02","difficulty":"easy","prompt":"ما المصدر الذي ترتكز إليه الدلائل النقلية على وجود الله تعالى؟","options":[{"id":"o1","text":"الوحي المنقول عن الأنبياء والرسل"},{"id":"o2","text":"المصادفة وحدها"},{"id":"o4","text":"ملاحظة النبات فقط دون غيره"},{"id":"o3","text":"الاجتهاد في مسائل الطب دون نص"}],"correct_id":"o1","explanation":"عرّف الكتاب الدلائل النقلية بأنها ما نقله الأنبياء والرسل من الوحي لتعريف الناس بربهم.","page":17},{"id":"u01_l02_q183","lesson_id":"u01_l02","difficulty":"medium","prompt":"طالب يذكر دقة عمل العين لا جمال صورتها فقط؛ إلى أي ناحية من حجة الإتقان يشير؟","options":[{"id":"o4","text":"أن المخلوقات لا تتفاوت في الخصائص"},{"id":"o1","text":"إحكام بناء العضو ووظيفته الدقيقة"},{"id":"o2","text":"أن أعضاء الجسم تعمل من دون ترابط"},{"id":"o3","text":"أن الإنسان يختار تركيب أعضائه قبل مولده"}],"correct_id":"o1","explanation":"يستشهد الدرس بدقة أجزاء العين ووظيفتها في إبراز الإتقان.","page":16},{"id":"u01_l02_q184","lesson_id":"u01_l02","difficulty":"hard","prompt":"ما الاستنتاج الذي يجمع بين انتظام حركة الأجرام وتناسق جسم الإنسان في عرض أدلة الوجود؟","options":[{"id":"o4","text":"أن التفكير في الكون يناقض الفطرة"},{"id":"o3","text":"أن مظهرًا واحدًا ينفي الحاجة إلى الاستدلال"},{"id":"o2","text":"أن كل الظواهر لا تخضع لأي نظام"},{"id":"o1","text":"تعدد المشاهد الكونية التي تشهد على دقة الصنع"}],"correct_id":"o1","explanation":"يدرج الشرح هذه المشاهد تحت انتظام الكون وإتقان الخلق.","page":16},{"id":"u01_l02_q185","lesson_id":"u01_l02","difficulty":"medium","prompt":"ما وجه الاستدلال بهداية المخلوقات إلى وسائل بقائها على العناية الإلهية؟","options":[{"id":"o4","text":"نشوء نظام الحياة من اختيار البشر وحدهم"},{"id":"o2","text":"استغناء كل مخلوق عن الطعام والبيئة"},{"id":"o1","text":"تيسير سبل المعيشة والانتفاع لكل مخلوق وفق خلقه"},{"id":"o3","text":"امتلاك المخلوقات علم الغيب المطلق"}],"correct_id":"o1","explanation":"يشرح دليل الهداية أن الله منح المخلوقات نظمًا تعينها على معيشتها.","page":17},{"id":"u01_l02_q186","lesson_id":"u01_l02","difficulty":"hard","prompt":"إذا اتخذ باحث مثال عودة المخلوق إلى موطنه بعد طلب رزقه، فأي جانب من الهداية يناقشه؟","options":[{"id":"o1","text":"اهتداء المخلوق إلى ما يصلح شؤون معيشته"},{"id":"o3","text":"انتقال الميراث بعد وفاة الإنسان"},{"id":"o2","text":"الهداية إلى تدوين النصوص الشرعية"},{"id":"o4","text":"إثبات التحدي القرآني البلاغي"}],"correct_id":"o1","explanation":"ربط الكتاب مشاهد هداية الحيوان بقدرته على تدبير ما ينفعه في حياته.","page":17},{"id":"u01_l02_q187","lesson_id":"u01_l02","difficulty":"medium","prompt":"ماذا تضيف النصوص المنقولة عن الرسل إلى التأمل العقلي في المخلوقات؟","options":[{"id":"o3","text":"تجعل الظواهر الطبيعية أحكامًا فقهية"},{"id":"o2","text":"تمنع النظر في الكون على الإطلاق"},{"id":"o4","text":"تحوّل الفطرة إلى دليل مادي محسوس"},{"id":"o1","text":"تعرّف الإنسان بالخالق عن طريق الوحي"}],"correct_id":"o1","explanation":"جعل الكتاب الدلائل النقلية مستندة إلى الوحي الذي جاء به الرسل.","page":17},{"id":"u01_l03_q105","lesson_id":"u01_l03","difficulty":"medium","prompt":"لماذا وُصفت دقة التقديم والتأخير في الألفاظ بأنها من الإعجاز البياني؟","options":[{"id":"o2","text":"لأن ترتيب الكلمات لا يغيّر المعنى مطلقًا"},{"id":"o3","text":"لأن كل الألفاظ تستخدم بمعنى واحد"},{"id":"o1","text":"لأن ترتيب الألفاظ يحمل دلالات مقصودة في السياق"},{"id":"o4","text":"لأن التقديم في الآيات أمر عشوائي"}],"correct_id":"o1","explanation":"يورد الدرس التقديم والتأخير مثالًا على الدقة البلاغية.","page":23},{"id":"u01_l03_q107","lesson_id":"u01_l03","difficulty":"medium","prompt":"بأي شرط ينبغي التعامل مع تفسير الآيات وفق الاكتشافات العلمية الحديثة؟","options":[{"id":"o2","text":"أن يُعدّ كل تخمين حقيقة قطعية"},{"id":"o3","text":"أن يهمل أهل الاختصاص عند البحث"},{"id":"o1","text":"ألا يبنى التفسير على فرضيات قابلة للتغير"},{"id":"o4","text":"أن تُغيّر الآيات لتوافق النظريات"}],"correct_id":"o1","explanation":"نبه الدرس إلى تجنب تحميل القرآن فرضيات علمية قد تتبدل.","page":24},{"id":"u01_l03_q113","lesson_id":"u01_l03","difficulty":"medium","prompt":"لماذا كان الانتقال من التحدي بعشر سور إلى التحدي بسورة واحدة ذا دلالة؟","options":[{"id":"o2","text":"لأن القرآن يتكون من عشر سور فقط"},{"id":"o4","text":"لأن السورة لا تحمل خصائص الإعجاز"},{"id":"o3","text":"لأن التحدي انتهى قبل نزول القرآن"},{"id":"o1","text":"لإظهار العجز حتى عن المقدار الأقل"}],"correct_id":"o1","explanation":"المرحلة الأخيرة في الخريطة هي التحدي بسورة واحدة بعد التحدي بمقدار أكبر.","page":22},{"id":"u01_l03_q116","lesson_id":"u01_l03","difficulty":"medium","prompt":"ما الغاية الرئيسة من ورود الإشارات العلمية في القرآن بحسب صندوق «أتوقف»؟","options":[{"id":"o3","text":"الاستغناء عن علوم الأخلاق والأحكام"},{"id":"o1","text":"خدمة هداية الإنسان وتوجيهه للعقيدة والسلوك الصحيح"},{"id":"o4","text":"حصر هدف القرآن في وصف الكواكب"},{"id":"o2","text":"تحويل القرآن إلى موسوعة تجريبية متغيرة"}],"correct_id":"o1","explanation":"بين الصندوق أن القرآن كتاب هداية وإرشاد والإشارات العلمية وسيلة لتحقيق هذا المقصد.","page":24},{"id":"u01_l03_q119","lesson_id":"u01_l03","difficulty":"hard","prompt":"إذا استُخدمت إشارة علمية لإثبات أن القرآن كتاب تجارب علمية أساسًا، فما الخلل في هذا الاستنتاج؟","options":[{"id":"o1","text":"جعل الوسيلة فرعًا هو المقصد الرئيس بدل الهداية والإرشاد"},{"id":"o3","text":"الرجوع إلى أهل الاختصاص"},{"id":"o2","text":"اعتبار العلم التجريبي أمرًا مفيدًا"},{"id":"o4","text":"التثبت من الحقائق بدل الفرضيات"}],"correct_id":"o1","explanation":"أكد الكتاب أن المقصد الرئيس للقرآن هو هداية الإنسان وأن الإشارات العلمية خادمة له.","page":24},{"id":"u01_l03_q133","lesson_id":"u01_l03","difficulty":"hard","prompt":"ما المقصود بإثبات العجز في تعريف «الإعجاز القرآني»؟","options":[{"id":"o4","text":"اختفاء أساليب البيان العربية"},{"id":"o1","text":"عدم قدرة الخلق على الإتيان بمثل القرآن أو بشيء من مثله"},{"id":"o3","text":"عجزهم عن حفظ سورة قصيرة"},{"id":"o2","text":"امتناع الناس عن قراءة القرآن"}],"correct_id":"o1","explanation":"التعريف في الدرس يتعلق بعدم قدرة الخلق على محاكاة القرآن.","page":22},{"id":"u01_l03_q139","lesson_id":"u01_l03","difficulty":"medium","prompt":"ما الأثر الذي يسعى إليه تنظيم العقوبات العادلة ضمن الإعجاز التشريعي؟","options":[{"id":"o2","text":"تشجيع الثأر بين الأسر"},{"id":"o4","text":"إلغاء مسؤولية المعتدي"},{"id":"o3","text":"توسيع الظلم باعتباره عقوبة"},{"id":"o1","text":"صيانة المجتمع والحقوق وردع الاعتداء"}],"correct_id":"o1","explanation":"عرض الدرس القصاص نموذجًا لحفظ الحياة وردع الاعتداء.","page":25},{"id":"u01_l03_q143","lesson_id":"u01_l03","difficulty":"medium","prompt":"حين طُلب الإتيان بعشر سور مماثلة، ما الذي تغيّر قياسًا بالتحدي الأول؟","options":[{"id":"o1","text":"انخفض مقدار المطلوب من مثل القرآن كله إلى عشر سور"},{"id":"o4","text":"ألغي تحدي البلاغة نهائيًا"},{"id":"o2","text":"انتقل التحدي إلى اختراع معجزة حسية"},{"id":"o3","text":"أصبح المطلوب سورة واحدة فقط في تلك المرحلة"}],"correct_id":"o1","explanation":"ترتيب التحدي في الدرس: الإتيان بمثله ثم عشر سور ثم سورة واحدة.","page":22},{"id":"u01_l03_q145","lesson_id":"u01_l03","difficulty":"medium","prompt":"لماذا اختير مثال الاستئناس قبل دخول بيوت الآخرين في باب الإعجاز البياني؟","options":[{"id":"o4","text":"لأنه يقصر الآداب على الضيوف"},{"id":"o1","text":"لأن دلالة اللفظ أوسع من مجرد طلب الإذن بالدخول"},{"id":"o3","text":"لأنه يحدد ميراث ساكن البيت"},{"id":"o2","text":"لأنه يغيّر عدد ركعات الصلاة"}],"correct_id":"o1","explanation":"بيّن الدرس ما تحمله كلمة الاستئناس من الأنس وإزالة الوحشة إلى جانب الإذن.","page":23},{"id":"u01_l03_q151","lesson_id":"u01_l03","difficulty":"medium","prompt":"أي عنصر يُميز المعجزة عن المهارة البشرية البارعة كما ورد في التعريف؟","options":[{"id":"o1","text":"أنها أمر خارق للعادة يؤيد به الله رسله ويقترن بالتحدي"},{"id":"o3","text":"أنها نتيجة تصويت الجمهور على حدث"},{"id":"o2","text":"أنها عمل عادي يتعلمه أي شخص بالتدريب"},{"id":"o4","text":"أنها مجرد خبر تاريخي لا علاقة له بالرسالة"}],"correct_id":"o1","explanation":"عرّف الكتاب المعجزة بالأمر الخارق للعادة الذي يظهر على يد الرسول تأييدًا لصدقه.","page":22},{"id":"u01_l03_q154","lesson_id":"u01_l03","difficulty":"hard","prompt":"إذا استعمل أحدهم كلمة مرادفة بدل لفظ قرآني ففقد بعض المعاني الدقيقة، فأي وجه إعجاز يوضحه المثال؟","options":[{"id":"o2","text":"الإعجاز الغيبي المحض"},{"id":"o1","text":"دقة اختيار الألفاظ وما تحمله من دلالات متكاملة"},{"id":"o3","text":"الأحكام المالية للميراث"},{"id":"o4","text":"تنظيم مؤسسات الوقف"}],"correct_id":"o1","explanation":"استدل الكتاب بلفظ الاستئناس على اتساع الدلالة ودقة اختيار الكلمة القرآنية.","page":23},{"id":"u01_l03_q162","lesson_id":"u01_l03","difficulty":"medium","prompt":"ما المرحلة التي جاءت بعد تحدي المشركين بالإتيان بمثل القرآن كله؟","options":[{"id":"o4","text":"التحدي بإبطال العبادات"},{"id":"o3","text":"التحدي بكتابة حديث نبوي"},{"id":"o1","text":"التحدي بالإتيان بعشر سور من مثله"},{"id":"o2","text":"التحدي بتغيير ترتيب المصحف"}],"correct_id":"o1","explanation":"حدد الدرس ثلاث مراحل تبدأ بمثل القرآن ثم عشر سور ثم سورة واحدة.","page":22},{"id":"u01_l03_q164","lesson_id":"u01_l03","difficulty":"medium","prompt":"إذا لم تفسر مرادفات لفظ قرآني دقائق المعنى كاملة، فبأي جانب من الإعجاز يتصل ذلك؟","options":[{"id":"o2","text":"الإعجاز الحسابي في توزيع الميراث"},{"id":"o3","text":"الإعجاز الإداري في إنشاء المؤسسات"},{"id":"o4","text":"تاريخ الرسائل النبوية إلى الملوك"},{"id":"o1","text":"الإعجاز البياني القائم على دقة اللفظ والسياق"}],"correct_id":"o1","explanation":"يتناول الإعجاز البياني اختيار الألفاظ وتناسبها مع السياق ودقتها.","page":23},{"id":"u01_l03_q172","lesson_id":"u01_l03","difficulty":"medium","prompt":"لماذا كانت المعجزات المادية لبعض الرسل مؤقتة ومختصة بقوم معينين؟","options":[{"id":"o2","text":"لأنها آيات لغوية يتعبد الناس بتلاوتها دائمًا"},{"id":"o1","text":"لارتباطها بالرسول والقوم الذين أرسل إليهم في زمنه"},{"id":"o3","text":"لأنها لا تظهر للناس في حياتهم مطلقًا"},{"id":"o4","text":"لأنها أحكام تفصيلية للميراث"}],"correct_id":"o1","explanation":"بيّن الكتاب أن المعجزات المادية محسوسة مؤقتة خاصة بالقوم الذين أرسل إليهم الرسول.","page":21},{"id":"u01_l03_q174","lesson_id":"u01_l03","difficulty":"medium","prompt":"ما الذي يظهره الانتقال في التحدي من القرآن كله إلى عشر سور ثم سورة واحدة؟","options":[{"id":"o3","text":"حصر البلاغة في عشر سور فقط"},{"id":"o4","text":"إمكان محاكاة القرآن بعد حذف السور"},{"id":"o2","text":"تراجع حجة القرآن عن إثبات مصدره"},{"id":"o1","text":"تأكيد العجز عن الإتيان بالمثل حتى بعد تخفيف مقدار المطلوب"}],"correct_id":"o1","explanation":"تدرج التحدي يثبت عجز المخاطَبين عن الإتيان بالمثل ولو بسورة.","page":22},{"id":"u01_l03_q175","lesson_id":"u01_l03","difficulty":"easy","prompt":"أي صورة من صور الإعجاز البياني تتمثل في اختيار لفظ أكثر دلالة من مرادف قريب؟","options":[{"id":"o3","text":"إخبار الناس بأحداث غيبية"},{"id":"o4","text":"ذكر مراحل تكون الجنين"},{"id":"o1","text":"الدقة في استعمال الألفاظ"},{"id":"o2","text":"تقسيم أموال التركة"}],"correct_id":"o1","explanation":"ذكر الكتاب دقة الألفاظ من صور الإعجاز البياني ومنها اختيار لفظ الاستئناس.","page":23},{"id":"u01_l03_q176","lesson_id":"u01_l03","difficulty":"medium","prompt":"لماذا عُدّ استعمال لفظ الاستئناس في آية دخول البيوت أدقّ من الاقتصار على الاستئذان؟","options":[{"id":"o4","text":"لأنه يدل على عقوبة السارق"},{"id":"o3","text":"لأنه يجيز الدخول دون إعلام الأسرة"},{"id":"o2","text":"لأنه يلغي حق صاحب البيت في رفض الدخول"},{"id":"o1","text":"لأنه يضم معنى الاستئذان وإشعار أهل البيت بالأمان والأُنس"}],"correct_id":"o1","explanation":"بيّن الشرح أن الاستئناس أوسع دلالة ويمنح أهل البيت فرصة الاستعداد لاستقبال القادم.","page":23},{"id":"u01_l03_q178","lesson_id":"u01_l03","difficulty":"easy","prompt":"كيف ينبغي التعامل مع نظرية علمية قابلة للتغير عند الحديث عن الإعجاز العلمي للقرآن؟","options":[{"id":"o1","text":"عدم جعلها تفسيرًا قطعيًا للإشارة القرآنية قبل ثبوتها"},{"id":"o2","text":"اعتبار كل فرضية علمية حقيقة لا تتغير"},{"id":"o3","text":"رفض كل حقيقة علمية ثابتة"},{"id":"o4","text":"تغيير ألفاظ ا